/**
 * Types for `lifted.js`, which is generated by `scripts/lift-journal.mjs` from
 * the journal app. The shape follows whatever the app still defines, so this
 * describes what the landing page relies on rather than everything exported.
 */

export interface LetterLike {
  id: string;
  date: string;
  private?: boolean;
  content: {
    tone?: string;
    headline?: string;
    themes?: string[];
    steps?: unknown[];
    analysis?: { quote?: string }[];
  };
}

export interface SkyState {
  list: LetterLike[];
  from: string;
  to: string;
  ticks: 'month' | 'year';
  theme: () => string | null;
}

export interface JournalComponents {
  THEMES: Record<string, string>;
  SECTIONS: Record<string, [string, string, string, string]>;
  VOICES: Record<string, Record<string, unknown>>;
  MON: string[];
  MONTH: string[];
  esc(s: unknown): string;
  cap(s: string): string;
  plural(n: number, one: string, many?: string): string;
  fmtDay(date: string): string;
  pad(n: number): string;
  dayDiff(a: string, b: string): number;
  seeded(key: string): () => number;
  countWords(text: string): number;
  realThemes(letter: LetterLike): string[];
  countThemes(letters: LetterLike[]): [string, number][];
  secLabel(section: string): string;
  lanternVars(words: number): string;
  skyCard(label: string, chips: [string, number][], selected: string | null): string;
  /** Draw the chart. Pass the state once; later calls redraw what is there. */
  chart(state?: SkyState): void;
  /** Which star is showing its card, by letter id, or null for none. */
  tip(id: string | null): void;
  tipId(): string | null;
}

export declare const APP: JournalComponents;
